INSERT INTO RAW_HL7_LAB_RESULT ( HL7_LAB_RESULT_ID, HL7_DOC_ID, HL7_LAB_TEST_ID, UPHN_TRANX_IN_ID, OBXSETID, OBXLOINCDESC, OBXLOINCCODE, OBXTESTCODE, OBXTESTDESC, OBXTESTCODINGSYSTEM, OBXALTTESTCODE, OBXALTTESTDESC, OBXALTTESTCODINGSYSTEM, OBXUNITOFMEASURE, OBXOBSERVATIONRESULTTEXT, OBXOBSERVATIONVALUETYPE, OBXNOTE, OBXREFERENCERANGE, OBXANORMALFLAG ) select raw_hl7_lab_result_seq.NEXTVAL,d.* from (
select #{hl7DocId, jdbcType=INTEGER}, #{labResultVO.hl7labTestId, jdbcType=INTEGER}, #{labResultVO.uphnTranxInId, jdbcType=INTEGER}, #{labResultVO.obxSetId, jdbcType=INTEGER}, #{labResultVO.obxLoincDesc, jdbcType=VARCHAR}, #{labResultVO.obxLoincCode, jdbcType=VARCHAR}, #{labResultVO.obxTestCode, jdbcType=VARCHAR}, #{labResultVO.obxTestDesc, jdbcType=VARCHAR}, #{labResultVO.obxTestCodingSystem, jdbcType=VARCHAR}, #{labResultVO.obxAltTestCode, jdbcType=VARCHAR}, #{labResultVO.obxAltTestDesc, jdbcType=VARCHAR}, #{labResultVO.obxAltTestCodingSystem, jdbcType=VARCHAR}, #{labResultVO.obxUnitOfMeasure, jdbcType=VARCHAR}, TO_CLOB(#{labResultVO.obxObservationResultText, jdbcType=VARCHAR}), #{labResultVO.obxObservationValueType, jdbcType=VARCHAR}, #{labResultVO.obxNote, jdbcType=VARCHAR}, #{labResultVO.obxReferenceRange, jdbcType=VARCHAR}, #{labResultVO.obxAbnormalFlag, jdbcType=VARCHAR} from dual
)d

mapper.select:
			
				DECLARE
                v_doc_id NUM_ARR;
                v_status VARCHAR2_NTT;
                CURSOR LCU IS SELECT r.document_id , CASE WHEN  R.PIDMPI IS NULL THEN 18
                                                          WHEN c.document_id IS NULL THEN 37 
                                          				  WHEN C.flux_MATCH_CD IN ('N','C_N','P_N') THEN 36 
                                          				  WHEN C.flux_MATCH_CD = 'C' THEN 37 ELSE 1 END process_status
              	              FROM RAW_HL7_DOC R , STD_CCD_DOC C 
                              WHERE R.CURRENT_PROCESS_STATUS IN (1,37,4)  -- ADD 36 later
              	 	 	 	  AND  R.PIDMPI=C.MPI (+);
				BEGIN
  				OPEN LCU;
  				LOOP
       					FETCH LCU
        				BULK COLLECT INTO v_doc_id,v_status LIMIT  10000;
        				FORALL indx IN INDICES OF v_doc_id
        				UPDATE RAW_HL7_DOC
        				SET CURRENT_PROCESS_STATUS = v_status(indx)
        				WHERE document_id = v_doc_id(indx);
        				EXIT WHEN v_doc_id.COUNT=0;
        		COMMIT;
  				END LOOP;
  				CLOSE LCU;
				END ;


{call match_ccd_hl7_records(
		#{p_days,jdbcType=INTEGER,mode=IN},
		#{p_process_status,jdbcType=VARCHAR,mode=IN},
